questionvariables.text:
/* Shared Question Bank Place Value, Rounding and Standard Form PVRS-08
Application task: use rounding appropriately in a real-world reporting context.
Original STACK question. No external mathematical content or wording is copied. */
/* Choose reporting precision.
1 = nearest ten 2 = nearest hundred 3 = nearest thousand */
place_choice: rand_with_prohib(1,3,[]);
place_value: if place_choice=1 then 10 elseif place_choice=2 then 100 else 1000;
place_name: if place_choice=1 then "ten" elseif place_choice=2 then "hundred" else "thousand";
/* Generate a realistic positive count.
The remainder is constructed so the quantity is not already an exact multiple of the reporting place. */
base_multiple: rand_with_prohib( 120, 950, [] ) * place_value;
/* Force the quantity into the upper half of the rounding interval.
This guarantees that correct rounding and simple truncation are different, so the secondary misconception is diagnostically meaningful in every variant. */
offset: rand_with_prohib( place_value/2, place_value-1, [] );
quantity: base_multiple + offset;
/* Explicit half-up rounding. */
answer: floor( ( quantity + place_value/2 ) / place_value ) * place_value;
/* Primary misconception: report the original exact count rather than the requested rounded quantity.
This represents unjustified precision in the reporting context. */
wrong_unrounded: quantity;
/* Secondary misconception: truncate rather than round. */
wrong_truncate: floor( quantity/place_value ) * place_value;
